def request = mockRequest.getRequest()
def origin = request.getParameter("origin")
def destination = request.getParameter("destination")
// City used as connection, it can not be the origin or the destination
def hubs = ['PTY', 'LIM', 'BOG', 'MIA', 'SAO'].findAll { it != origin && it != destination }
def random = new Random()
requestContext.hub = hubs[random.nextInt(hubs.size())]
// The same carrier is used in the itinerary and in the number of each flight
def carriers = ['AR', 'AA', 'DL']
(0..4).each { requestContext.put("carrier" + it, carriers[random.nextInt(carriers.size())]) }
def cabin = (request.getParameter("cabin") ?: "ECONOMY").toLowerCase().replace('_', '-')
if (!(cabin in ['economy', 'premium-economy', 'business'])) {
    cabin = 'economy'
}
def trip = request.getParameter("returnDate") ? "round-trip" : "one-way"
return trip + "-" + cabin
